```c++
#include <bits/stdc++.h>
using namespace std;

int m, n;
string s;
int dp[2][100010];

void solve() {
    memset(dp, 0x3f, sizeof dp);
    dp[0][0] = 0;
    for (int i = 0; i < n; i += 2) {
        if (s[i] == '(') dp[0][i + 1] = 0;
        for (int j = i - 1; j >= 0; j -= 2) {
            if (s[j] == ')') {
                dp[1][j + 1] = min(dp[1][j + 1], dp[0][i] + j - i + 1);
            }
            dp[0][i] = min(dp[0][i], dp[1][j] + i - j);
        }
        swap(dp[0], dp[1]);
    }
    cout << dp[0][n] << endl;
}

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cin >> m;
    for (int t = 1; t <= m; t++) {
        cin >> n >> s;
        if (s.size() != n) s.resize(n);
        for (int i = 1; i < n; i += 2) s[i] = '_';
        solve();
    }
    return 0;
}
```
Explanation:

The problem can be solved using dynamic programming. Let dp[0][i] be the minimum cost of a regular bracket sequence that can be obtained from s by replacing `'_'`-s with brackets for even indices from 0 to i. The base case is dp[0][0] = 0, since an empty sequence has cost 0.

For an even index i, dp[0][i] is the minimum of two cases:

1. If s[i] is an opening bracket, dp[0][i] = 0, since we can pair it with the closing bracket at index i+1.
2. Otherwise, for all odd indices j < i, dp[0][i] is the minimum of the cost of a regular bracket sequence obtained from s by replacing `'_'`-s with brackets for even indices from 0 to j and the cost of a regular bracket sequence obtained from s by replacing `'_'`-s with brackets for even indices from j+1 to i, with an additional cost of i-j+1 for the distance between the opening and closing brackets at indices j and i+1.

At the end of the algorithm, dp[0][n] will be the answer.

Time Complexity: O(n^2)
Space Complexity: O(n)

```c
#include<bits/stdc++.h>
using namespace std;
#define MOD 1000000007
#define fi first
#define se second
typedef pair<int,int> pii;
const int MX = 1e5+5;
int n,a[MX];

int dp[MX][2];

int f(int l,bool last) {
    if (l > n) return 0;

    if (dp[l][last]!=-1) return dp[l][last];

    if (last) dp[l][last] = (f(l+2,0)+MOD)%MOD;
    else dp[l][last] = min(f(l+2,0)+MOD,f(l+1,1)+1+(f(l+2,0)+MOD));
    return dp[l][last];
}

