    for (int i = 2; i <= n; i += 2) {
        p[i] = p[i - 2];
        if (s[i] == '(') p[i]++;
        else if (s[i] == ')') p[i]--;
    }
}

int sol() {
    int cnt = 0, sum = 0;
    for (int i = 2; i <= n; i += 2) {
        if (p[i] != 0) {
            cnt++;
            sum += abs(p[i]);
        }
    }
