void build(int p, int l, int r) {
    if (l > r) return;

    tree[sz++] = {l, r, 0};

    if (l == r) return;

    int mid = (l + r) >> 1;

    build(mid * 2, l, mid);
    build(mid * 2 + 1, mid + 1, r);
}

int get_min(int p, int l, int r, int s) {
    if (l == r) return tree[p].l - tree[p].r + s;

    int mid = (l + r) >> 1;

    if (r <= mid) return get_min(p * 2, l, mid, s);
    if (l > mid) return get_min(p * 2 + 1, mid + 1, r, s);

    return min(get_min(p * 2, l, mid, s), get_min(p * 2 + 1, mid + 1, r, s));
}

int solve(string s) {
    int n = s.length(), cnt = 0;

    for (int i = 0; i < n; i++) {
        if (i & 1) {
            if (s[i] == ')') cnt++;
        } else {
            if (s[i] == '(') cnt++;
            else cnt--;
        }
    }

    if (cnt & 1) return -1;

    build(1, 0, n - 1);

    int ans = INT_MAX;
    for (int i = 0; i < n; i++) {
        if (i & 1) {
            if (s[i] == '_') {
                s[i] = '(';
                int cost = get_min(1, 0, n - 1, 1);
                s[i] = '_';
                cost += get_min(1, 0, n - 1, -1);

                ans = min(ans, cost);
            }
        }
    }

    return ans;
}

