    for (int i = 0; i < n / 2; ++i) {
        int costLeft = cost[i];
        int costRight = cost[n / 2 - i - 1];
        if (i > 0 && costLeft > costRight)
            swap(costLeft, costRight);

        minCost = min(minCost, costLeft + costRight);
    }

    cout << minCost << endl;
}

