import React, { useState, useEffect } from 'react';
import { useDebounce } from 'use-debounce';
import { Suggestion } from './types';

type Props = {
  options: Suggestion[];
  onChange: (suggestion: Suggestion | null) => void;
  placeholder: string;
};

const Input: React.FC<Props> = ({ options, onChange, placeholder }) => {
  const [value, setValue] = useState('');
  const [filteredOptions, setFilteredOptions] = useState<Suggestion[]>([]);
  const [debouncedValue] = useDebounce(value, 500);

  useEffect(() => {
    const filtered = options.filter(option =>
      option.label.toLowerCase().includes(debouncedValue.toLowerCase())
    );
    setFilteredOptions(filtered);
  }, [debouncedValue, options]);

  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const inputValue = event.target.value;
    setValue(inputValue);
    onChange(inputValue ? options.find(option => option.label === inputValue) : null);
  };

  return (
    <div className="input-container">
      <input
        type="text"
        placeholder={placeholder}
        value={value}
        onChange={handleInputChange}
        className={`input ${value && !filteredOptions.length ? 'invalid' : ''}`}
      />
      {filteredOptions.length > 0 && (
        <ul className="suggestions">
          {filteredOptions.map(option => (
            <li key={option.id} onClick={() => onChange(option)}>{option.label}</li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default Input;
```

First, we define the props for the component. We have an `options` array with suggestion objects, an `onChange` function to handle changes in the input, and a `placeholder` string for the input field.

Next, we create state variables for the input value, filtered options, and debounced value (with the useDebounce hook).

In the `useEffect` hook, we filter the `options` based on the `debouncedValue` and update the `filteredOptions` state.

When the input value changes, we call the `handleInputChange` function. This updates the input value, triggers the onChange callback with the selected option (if any), and checks if the input value is valid (i.e., if it's a valid suggestion in the options array). If the input value is invalid, we add the "invalid" CSS class to the input container.

Finally, we render the input field, suggestions list, and update the styles accordingly.

