      control={control}
      defaultValue=""
      render={({ value, onChange }) => (
        <div className="dynamic-input">
          <label>{label}</label>
          <Select
            className="dynamic-input__select"
            classNamePrefix="select"
            components={animatedComponents}
            options={filteredOptions.slice(0, 10)}
            value={selectedOption}
            onChange={handleChange}
            onInputChange={({ newValue }) => setInputValue(newValue as string)}
            isSearchable
            isClearable
            isDisabled={disabled}
            inputRef={(ref) => ref && ref.onKeyDown(handleKeyDown)}
          />
          {errors[name] && (
            <div className="dynamic-input__error">{errors[name].message}</div>
          )}
        </div>
      )}
    />
  );
};

export default DynamicInput;
```

