  const [filteredOptions, showDropdown] = useDropdown<Option>(value, options);

  const handleInputChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setValue(event.target.value);
  };

  const handleOptionClick = (option: Option) => {
    setValue(option.value);
    showDropdown(false);
    onChange(option.value);
  };

  return (
    <>
      <Input label={label} value={value} onChange={handleInputChange} />
      {showDropdown && (
        <Dropdown>
          {filteredOptions.map((option) => (
            <div key={option.value} onClick={() => handleOptionClick(option)}>
              {option.label}
            </div>
          ))}
        </Dropdown>
      )}
    </>
  );
};
```

In the code above, we created a reusable `InputComponent` that accepts the `label`, `options`, `validate`, and `onChange` props. The component uses the `useState` and `useEffect` hooks for handling user input and the dropdown menu. The `useDropdown` hook is created to manage the dropdown menu and filtering the options based on the user input.

The `useDropdown` hook compares the current user input (`value`) with the options array and filters it accordingly. If the user input is an empty string, the dropdown menu should not be shown (`showDropdown(false)`).

```typescript
import React, { useState, useEffect } from 'react';

type TItem = {
  value: string;
  label: string;
};

export const useDropdown = (value: string, items: TItem[]) => {
  const [filteredItems, setFilteredItems] = useState<TItem[]>(items);
  const [showDropdown, setShowDropdown] = useState<boolean>(false);

  useEffect(() => {
    if (value === '') {
      setFilteredItems(items);
      setShowDropdown(false);
    } else {
      const filtered = items.filter((item) => item.value.includes(value));
      setFilteredItems(filtered);
      setShowDropdown(true);
    }
  }, [value, items]);

  return [filteredItems, showDropdown];
};
```

